The prior shell attempt failed due to quoting, so I’m recomputing directly with exact rational dynamic programming. I’ll propagate all reachable platform states, record which ball is ejected, and select the maximum-probability ball.
```python
from fractions import Fraction

states = {(1, 2, 3, 4): Fraction(1)}
ejected = {}
steps = 0

while states:
    nxt = {}
    for (a, b, c, k), mass in states.items():
        if a is None and b is None and c is None:
            continue
        for piston in (1, 2, 3):
            q = mass / 3
            if piston == 1:
                if a is not None:
                    ejected[a] = ejected.get(a, Fraction(0)) + q
                new_a, new_b, new_c = b, c, (k if k <= 100 else None)
                new_k = k + 1
            elif piston == 2:
                if b is not None:
                    ejected[b] = ejected.get(b, Fraction(0)) + q
                new_a, new_b = c, (k if k <= 100 else None)
                new_c = (k + 1 if k + 1 <= 100 else None)
                new_k = k + 2
            else:
                if c is not None:
                    ejected[c] = ejected.get(c, Fraction(0)) + q
                new_a, new_b = b, (k if k <= 100 else None)
                new_c = (k + 1 if k + 1 <= 100 else None)
                new_k = k + 2
            ns = (new_a, new_b, new_c, new_k)
            nxt[ns] = nxt.get(ns, Fraction(0)) + q
    states = nxt
    steps += 1

best_probability = max(ejected.values())
best_balls = [ball for ball, p in ejected.items() if p == best_probability]
print(f"best_balls={best_balls}, probability={best_probability}, decimal={float(best_probability)}, steps={steps}")
```

